out = []
P = out.append
n = len(ITEMS)
from collections import Counter
c = Counter(i["sev"] for i in ITEMS)
TRACKER = sys.argv[1] if len(sys.argv) > 1 else "(filed at stage D)"
P("# Punch List — M6.P2 T30, the standalone emulators (#677)\n")
P("**Generated:** 2026-10-24 (Phase 5, after Phase 4.6)  ")
P("**Source Audit:** `04-analysis.md` (Risk Assessment, Renovation face, § Second opinion)  ")
P(f"**Total Items:** {n} (Critical: {c['Critical']}, High: {c['High']}, Medium: {c['Medium']}, Low: {c['Low']})  ")
P(f"**Punch-list tracker:** {TRACKER} (a sub-issue of #677)\n")
P("Generated by `tools/punch-items.py` from one list, so the items, the `punch_index` and the Phase 7 table agree. `aethersx2-sa`'s rows are `deferred: base merge, class 1` (upstream's `c4d353449e`); an item upstream has already fixed after the base names the commit as its class-1 route.\n")
P("---\n\n## Instructions for Executing Agent\n")
P("The lane does not start on these: the coordinator writes one remediation brief per stream of related items (plan § 6b stage E; the **Owner area** is the proposed stream). Each fix carries its `Already written:` line and its two runs.\n\n---\n")
for i in ITEMS:
    P(f"## {i['id']}: {i['title']}\n")
    P(f"- **Severity:** {i['sev']}")
    P(f"- **Category:** {i['cat']}")
    P(f"- **Question:** {i['q']}")
    P(f"- **Source Finding:** {i['src']}")
    P(f"- **Owner area:** {i['area']}")
    P(f"- **What:** {i['what']}")
    P(f"- **Where:** `{i['where']}`")
    P(f"- **Evidence:** {i['ev']}")
    P(f"- **Can this be done on the VM?** {i['vm']}")
    P(f"- **Already written:** {i['aw']}")
    P(f"- **Acceptance:** {i['acc']}")
    if i.get("tracked"): P(f"- **Tracked work:** {i['tracked']}")
    if i.get("note"): P(f"- **Disposition note:** {i['note']}")
    P("")
P("## Phase 7 resolution gate\n")
P("| Item | Outcome | Evidence / reason |\n| --- | --- | --- |")
word = {"open": "Open", "deferred": "Deferred", "resolved": "Resolved", "withdrawn": "Withdrawn"}
for i in ITEMS:
    reason = i.get("note") or "awaiting the coordinator's stream briefs (stage E)"
    if i["disp"] == "deferred" and i.get("tracked"): reason = f"{i['tracked']}: " + reason
    P(f"| {i['id']} | {word[i['disp']]} | {reason} |")
P("\n## Machine-readable index\n\n```yaml\npunch_index:")
for i in ITEMS:
    P(f"- id: {i['id']}\n  severity: {i['sev']}\n  category: {i['cat']}\n  question: {i['q']}\n  source_finding: \"{i['src']}\"\n  owner_area: \"{i['area']}\"")
    if i.get("tracked"): P(f"  tracked: \"{i['tracked']}\"")
    if i.get("removal"): P("  removal: yes")
    if i.get("state"): P(f"  state: {i['state']}")
    P(f"  outcome: {i['disp']}")
P("```")
sys.stdout.write("\n".join(out) + "\n")
